    apiKeyEnvNames: ['DIAL_API_KEY'],
    contextWindow: 200000,
    maxTokens: 16384,
  ),
  'minimax': ProviderSpec(
    name: 'minimax',
    // Chat is OpenAI-compatible (MiniMax-M3 works via the OpenAI completions
