String? cubeSource;
CubeSpec? cubeSpec;
try {
  cubeSource = resolveStartupCubeSource(
    flagConfigPath: parsed.cubeConfigPath,
    flagName: parsed.cubeName,
    project: loadProjectCubeSettings(cwd),
    user: saved.cube,
