  Message? lastMessage, {
  required bool isAutoContinue,
}) async {
  if (lastMessage is AssistantMessage &&
      lastMessage.stopReason == StopReason.error) {
    if (await _maybeHandleCodeMieError(lastMessage.errorMessage ?? '')) {
      return false;
