  'sonnet': {
    '3.0': 4096,
    '3.5': 8192,
    '3.7': 8192,
    '4.0': 64000,
    '4.1': 64000,
    '4.2': 64000,
    '4.3': 64000,
    '4.4': 64000,
    '4.5': 64000,
    '4.6': 128000,
    '5.0': 128000,
  },
  'haiku': {'3.0': 4096, '3.5': 8192, '4.5': 64000},
