+  group('buildCliDefaultModel catalog coverage (gh-760)', () {
+    test('every catalog name and kind resolves (REG-C1)', () {
+      final keys = <String>{
+        for (final spec in providerCatalog.values) ...[spec.name, spec.kind],
+      };
+      expect(keys, isNotEmpty);
