    // so providerStreamFunction routes it to the OpenAI completions adapter.
    kind: 'aiin',
    api: 'openai-completions',
    defaultBaseUrl: '$aiinApiBaseUrl/v1',
    apiKeyEnvNames: ['AIIN_API_KEY'],
    contextWindow: 200000,
    maxTokens: 16384,
